"""Industry-specific synthetic test packs for regulated and operational domains."""


def m(slug: str, label: str, tasks: str):
    return slug, label, [task.strip() for task in tasks.split("|") if task.strip()]


def pack(root, key, display, prefix, accent, domain, modules, journeys, safety):
    return {
        "root": root,
        "key": key,
        "display": display,
        "prefix": prefix,
        "accent": accent,
        "industryDomain": domain,
        "modules": modules,
        "journeys": journeys,
        "safetyNote": safety,
    }


